const now = new Date();
const day = now.getDate();
const isMonthly = day === 1;

let startDate, endDate;
if (isMonthly) {
  const y = now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();
  const m = now.getMonth() === 0 ? 11 : now.getMonth() - 1;
  startDate = new Date(y, m, 1);
  endDate   = new Date(y, m + 1, 0);
} else {
  endDate   = new Date(now);
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 7);
}

const fmt = d => d.toISOString().split('T')[0];

return [{ json: {
  period:     isMonthly ? 'Mensal' : 'Semanal',
  start_date: fmt(startDate),
  end_date:   fmt(endDate)
}}];

// ⚠️ EDIT: one entry per GA4 property
// property_id: from GA4 Admin > Property Settings (numeric ID only, e.g. '123456789')
// label:       display name shown in Discord embed title
// webhook_url: Discord webhook URL for this property's channel
const properties = [
  {
    property_id: 'SEU_PROPERTY_ID_1',
    label:       'Site Principal',
    webhook_url: 'https://discord.com/api/webhooks/SEU_WEBHOOK_1'
  },
  // {
  //   property_id: 'SEU_PROPERTY_ID_2',
  //   label:       'Site Secundário',
  //   webhook_url: 'https://discord.com/api/webhooks/SEU_WEBHOOK_2'
  // },
];
return properties.map(p => ({ json: p }));

const gaResults   = $input.all();
const propConfigs = $('GA Properties Config').all();
const period      = $('Set Period').first().json;

const Num = (n, dec) => n != null
  ? Number(n).toLocaleString('pt-BR', { minimumFractionDigits: dec ?? 0, maximumFractionDigits: dec ?? 0 })
  : '—';

const results = [];
for (let i = 0; i < gaResults.length; i++) {
  const raw  = gaResults[i].json;
  const prop = (propConfigs[i] ?? propConfigs[0]).json;

  // Handle both n8n-normalised format (direct fields) and raw GA4 API response ({rows, metricHeaders})
  let m;
  if (Array.isArray(raw.rows)) {
    const row = raw.rows[0] ?? { metricValues: [] };
    m = {};
    (raw.metricHeaders ?? []).forEach((h, j) => { m[h.name] = row.metricValues[j]?.value ?? '0'; });
  } else {
    m = raw;
  }

  const totalUsers  = parseInt(m.totalUsers            || 0);
  const sessions    = parseInt(m.sessions               || 0);
  const pageViews   = parseInt(m.screenPageViews        || 0);
  const eventCount  = parseInt(m.eventCount             || 0);
  const engRate     = parseFloat(m.engagementRate       || 0) * 100;
  const engDuration = parseFloat(m.userEngagementDuration || 0);
  const avgEngSec   = sessions > 0 ? Math.round(engDuration / sessions) : 0;

  const color = period.period === 'Mensal' ? 0x5865F2 : 0x57F287;

  const payload = {
    embeds: [{
      title: `📊 Google Analytics — ${prop.label} — ${period.period}`,
      description: `📅 Período: **${period.start_date}** até **${period.end_date}**`,
      color,
      fields: [
        { name: '👥 Usuários',             value: `**${Num(totalUsers)}**`,       inline: true },
        { name: '🔁 Sessões',              value: `**${Num(sessions)}**`,         inline: true },
        { name: '📄 Pageviews',            value: `**${Num(pageViews)}**`,        inline: true },
        { name: '⚡ Engajamento',          value: `**${engRate.toFixed(1)}%**`,   inline: true },
        { name: '🎯 Eventos',              value: `**${Num(eventCount)}**`,       inline: true },
        { name: '⏱️ Tempo Médio Eng.',     value: `**${Num(avgEngSec)}s**`,       inline: true },
      ],
      footer: {
        text: `Gerado em ${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}`
      }
    }]
  };

  results.push({ json: { payload, webhook_url: prop.webhook_url } });
}
return results;
